import React, { useState } from "react";
import axios from "axios";

const initialState = {
  age: "",
  memory_score: "",
  brain_volume: "",
  genetic_risk: "",
  bmi: "",
  hypertension: "",
  education_level: ""
};

const PredictionPage = () => {
  const [formData, setFormData] = useState(initialState);
  const [modelType, setModelType] = useState("rf");
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const values = Object.values(formData).map(Number);
    if (values.some(isNaN)) {
      alert("Please fill all fields with numeric values.");
      return;
    }

    setLoading(true);
    try {
      const res = await axios.post("http://localhost:5000/predict", {
        inputData: values,
        modelType,
      });
      setResult(res.data.prediction === 1 ? "Alzheimer's Detected" : "No Alzheimer's Detected");
    } catch (error) {
      console.error(error);
      setResult("Prediction failed.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ padding: "2rem", fontFamily: "Arial" }}>
      <h2>Alzheimer's Disease Prediction</h2>
      <form onSubmit={handleSubmit}>
        {Object.keys(formData).map((key) => (
          <div key={key}>
            <label>
              {key.replace("_", " ").toUpperCase()}:{" "}
              <input
                type="number"
                name={key}
                value={formData[key]}
                onChange={handleChange}
                required
              />
            </label>
          </div>
        ))}

        <div>
          <label>Select Model: </label>
          <select value={modelType} onChange={(e) => setModelType(e.target.value)}>
            <option value="rf">Random Forest</option>
            <option value="svm">SVM</option>
            <option value="cnn">CNN</option>
          </select>
        </div>

        <button type="submit" disabled={loading}>
          {loading ? "Predicting..." : "Predict"}
        </button>
      </form>

      {result && (
        <div style={{ marginTop: "1rem", fontWeight: "bold" }}>
          Prediction Result: {result}
        </div>
      )}
    </div>
  );
};

export default PredictionPage;
